steps.solution:
#include <iostream>
using namespace std;

int main() {
    int sol = 14;
    double gravity = 3.73;
    char sector = 'A';
    bool active = true;

    cout << "SOL: " << sol << " (" << sizeof(sol) << " B)" << endl;
    cout << "GRAVITY: " << gravity << " (" << sizeof(gravity) << " B)" << endl;
    cout << "SECTOR: " << sector << " (" << sizeof(sector) << " B)" << endl;
    cout << "ACTIVE: " << active << " (" << sizeof(active) << " B)" << endl;
    return 0;
}
